Here's your water tracker. Tap a glass or use + and − to count, and it fills up toward 8 glasses.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; text-align: center; margin: 0; padding: 24px; background: #f2f8fc; color: #12384f; }
  h1 { font-size: 1.3rem; margin: 0 0 4px; }
  #date { font-size: .85rem; opacity: .7; margin-bottom: 16px; }
  #count { font-size: 3rem; font-weight: 700; }
  #msg { min-height: 1.4em; margin: 4px 0 16px; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 360px; margin: 0 auto 20px; }
  .g { width: 56px; height: 72px; border: 3px solid #3a8fc0; border-radius: 6px 6px 14px 14px; background: #fff; cursor: pointer; padding: 0; }
  .g.full { background: linear-gradient(#7cc4ec, #3a8fc0); }
  .bar { height: 10px; background: #d6e8f3; border-radius: 5px; max-width: 360px; margin: 0 auto 20px; overflow: hidden; }
  #fill { height: 100%; width: 0; background: #3a8fc0; transition: width .3s; }
  button.b { font-size: 1.1rem; padding: 8px 18px; margin: 0 4px; border: 0; border-radius: 8px; background: #3a8fc0; color: #fff; cursor: pointer; }
  button.b.alt { background: #8aa7b8; }
</style>
</head>
<body>
  <h1>Daily water</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="glasses"></div>
  <div class="bar"><div id="fill"></div></div>
  <button class="b" id="minus">−</button>
  <button class="b" id="plus">+</button>
  <button class="b alt" id="reset">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = new Date().toDateString();
  var box = document.getElementById("glasses");
  for (var i = 0; i < GOAL; i++) {
    (function (i) {
      var b = document.createElement("button");
      b.className = "g";
      b.setAttribute("aria-label", "Glass " + (i + 1));
      b.onclick = function () { set(n === i + 1 ? i : i + 1); };
      box.appendChild(b);
    })(i);
  }
  function set(v) {
    n = Math.max(0, Math.min(20, v));
    try { localStorage.setItem(key, n); } catch (e) {}
    render();
  }
  function render() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var gs = box.children;
    for (var i = 0; i < gs.length; i++) gs[i].className = "g" + (i < n ? " full" : "");
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal done. Nicely hydrated! 💧" : (GOAL - n) + " more to go";
  }
  document.getElementById("plus").onclick = function () { set(n + 1); };
  document.getElementById("minus").onclick = function () { set(n - 1); };
  document.getElementById("reset").onclick = function () { set(0); };
  render();
</script>
</body>
</html>
```

It starts fresh each day. If your screen doesn't save between visits, the count resets when you close it.
